        dropped.add(j);
      }
    }
    open.push(i);
  }
  const seen = new Set<string>();
  const classified: ClassifiedSecret[] = [];
  matches.forEach((match, i) => {
    if (!dropped.has(i) && !seen.has(match.item.secret)) {
      seen.add(match.item.secret);
      classified.push(match.item);
    }
